// TestPackCodecs is the acceptance test for "Codecs recorded at publish"
// (playback-capability-gate 2.1, D2): the pure composition table covers every
// admitted family and degrades unknown facts to absent, and a real pack
// records the codecs of its published init segments — cross-checked against
// ffprobe of the same artifact, so the artifact is the oracle.
func TestPackCodecs(t *testing.T) {
	ctx := context.Background()

	t.Run("composition_table", func(t *testing.T) {
		cases := []struct {
			name   string
			stream string // verbatim-shape ffprobe stream JSON
			want   string // "" = the record degrades to absent
		}{
			// avc1: profile table + level byte (constraint constants are per the
			// documented table in codecs.go).
			{name: "avc1_high_l51", stream: `{"codec_type":"video","codec_name":"h264","profile":"High","level":51}`, want: "avc1.640033"},
			{name: "avc1_high_l40", stream: `{"codec_type":"video","codec_name":"h264","profile":"High","level":40}`, want: "avc1.640028"},
			{name: "avc1_main_l31", stream: `{"codec_type":"video","codec_name":"h264","profile":"Main","level":31}`, want: "avc1.4D401F"},
			{name: "avc1_baseline_l30", stream: `{"codec_type":"video","codec_name":"h264","profile":"Baseline","level":30}`, want: "avc1.42001E"},
			{name: "avc1_constrained_baseline_l30", stream: `{"codec_type":"video","codec_name":"h264","profile":"Constrained Baseline","level":30}`, want: "avc1.42401E"},

			// Fail-open degradation: missing/unknown facts compose nothing.
			{name: "avc1_missing_level_degrades", stream: `{"codec_type":"video","codec_name":"h264","profile":"High"}`, want: ""},
			{name: "avc1_unknown_level_degrades", stream: `{"codec_type":"video","codec_name":"h264","profile":"High","level":-99}`, want: ""},
			{name: "avc1_high10_degrades", stream: `{"codec_type":"video","codec_name":"h264","profile":"High 10","level":40}`, want: ""},

			// hvc1/hev1: the sample-entry tag is read from the probed artifact.
			{name: "hvc1_main_l120", stream: `{"codec_type":"video","codec_name":"hevc","codec_tag_string":"hvc1","profile":"Main","level":120}`, want: "hvc1.1.6.L120.B0"},
			{name: "hvc1_main10_l153", stream: `{"codec_type":"video","codec_name":"hevc","codec_tag_string":"hvc1","profile":"Main 10","level":153}`, want: "hvc1.2.4.L153.B0"},
			{name: "hev1_main_l93", stream: `{"codec_type":"video","codec_name":"hevc","codec_tag_string":"hev1","profile":"Main","level":93}`, want: "hev1.1.6.L93.B0"},
			{name: "hevc_missing_tag_degrades", stream: `{"codec_type":"video","codec_name":"hevc","profile":"Main","level":120}`, want: ""},
			{name: "hevc_foreign_tag_degrades", stream: `{"codec_type":"video","codec_name":"hevc","codec_tag_string":"hvcC","profile":"Main","level":120}`, want: ""},
			{name: "hevc_rext_degrades", stream: `{"codec_type":"video","codec_name":"hevc","codec_tag_string":"hvc1","profile":"Rext","level":120}`, want: ""},
			{name: "hevc_missing_level_degrades", stream: `{"codec_type":"video","codec_name":"hevc","codec_tag_string":"hvc1","profile":"Main"}`, want: ""},

			// Audio: AAC-LC is the admitted composition; an AAC the table has no
			// profile fact for degrades.
			{name: "mp4a_aac_lc", stream: `{"codec_type":"audio","codec_name":"aac","profile":"LC"}`, want: "mp4a.40.2"},
			{name: "aac_unprofiled_degrades", stream: `{"codec_type":"audio","codec_name":"aac"}`, want: ""},

			// The profile-free audio families.
			{name: "mp3", stream: `{"codec_type":"audio","codec_name":"mp3"}`, want: "mp3"},
			{name: "opus", stream: `{"codec_type":"audio","codec_name":"opus"}`, want: "opus"},
			{name: "flac", stream: `{"codec_type":"audio","codec_name":"flac"}`, want: "flac"},
			{name: "ac3", stream: `{"codec_type":"audio","codec_name":"ac3"}`, want: "ac-3"},
			{name: "eac3", stream: `{"codec_type":"audio","codec_name":"eac3"}`, want: "ec-3"},
			{name: "vorbis", stream: `{"codec_type":"audio","codec_name":"vorbis"}`, want: "vorbis"},

			// Anything outside the admitted families degrades.
			{name: "dts_degrades", stream: `{"codec_type":"audio","codec_name":"dts"}`, want: ""},
			{name: "mpeg4_video_degrades", stream: `{"codec_type":"video","codec_name":"mpeg4","profile":"Simple Profile","level":0}`, want: ""},
			{name: "empty_stream_degrades", stream: `{}`, want: ""},
		}
		for _, tc := range cases {
			tc := tc
			t.Run(tc.name, func(t *testing.T) {
				var s map[string]any
				if err := json.Unmarshal([]byte(tc.stream), &s); err != nil {
					t.Fatalf("unmarshal stream fixture: %v", err)
				}
				if got := codecString(s); got != tc.want {
					t.Errorf("codecString = %q, want %q", got, tc.want)
				}
			})
		}
	})

	// The legacy read-side table (pack-manifest-audio 2.1, finding B): the
	// HEVC sample-entry tag is COMPOSED over stored source facts — verbatim
	// hvc1/hev1, anything else (a container artifact) as the hvc1 default —
	// while every other family composes exactly as the publish table does.
	t.Run("legacy_composition_table", func(t *testing.T) {
		cases := []struct {
			name   string
			stream string
			want   string
		}{
			{name: "legacy_matroska_tag_composes_hvc1", stream: `{"codec_type":"video","codec_name":"hevc","codec_tag_string":"[0][0][0][0]","profile":"Main 10","level":120}`, want: "hvc1.2.4.L120.B0"},
			{name: "legacy_hvc1_verbatim", stream: `{"codec_type":"video","codec_name":"hevc","codec_tag_string":"hvc1","profile":"Main","level":120}`, want: "hvc1.1.6.L120.B0"},
			{name: "legacy_hev1_verbatim", stream: `{"codec_type":"video","codec_name":"hevc","codec_tag_string":"hev1","profile":"Main","level":93}`, want: "hev1.1.6.L93.B0"},
			{name: "legacy_foreign_tag_composes_hvc1", stream: `{"codec_type":"video","codec_name":"hevc","codec_tag_string":"hvcC","profile":"Main","level":120}`, want: "hvc1.1.6.L120.B0"},

			// Only the tag rule diverges: the rest of the table degrades the
			// same way it does at publish.
			{name: "legacy_rext_still_degrades", stream: `{"codec_type":"video","codec_name":"hevc","codec_tag_string":"[0][0][0][0]","profile":"Rext","level":120}`, want: ""},
			{name: "legacy_missing_level_still_degrades", stream: `{"codec_type":"video","codec_name":"hevc","codec_tag_string":"[0][0][0][0]","profile":"Main"}`, want: ""},
			{name: "legacy_avc1_unchanged", stream: `{"codec_type":"video","codec_name":"h264","profile":"High","level":51}`, want: "avc1.640033"},
			{name: "legacy_aac_unchanged", stream: `{"codec_type":"audio","codec_name":"aac","profile":"LC"}`, want: "mp4a.40.2"},
		}
		for _, tc := range cases {
			tc := tc
			t.Run(tc.name, func(t *testing.T) {
				var s map[string]any
				if err := json.Unmarshal([]byte(tc.stream), &s); err != nil {
					t.Fatalf("unmarshal stream fixture: %v", err)
				}
				if got := legacyCodecString(s); got != tc.want {
					t.Errorf("legacyCodecString = %q, want %q", got, tc.want)
				}
			})
		}
	})

	// The publish-time table stays verbatim-or-degrade even where the legacy
	// path composes: the probed artifact carries the muxer's real entry.
	t.Run("publish_still_verbatim_where_legacy_composes", func(t *testing.T) {
		var s map[string]any
		stream := `{"codec_type":"video","codec_name":"hevc","codec_tag_string":"[0][0][0][0]","profile":"Main 10","level":120}`
		if err := json.Unmarshal([]byte(stream), &s); err != nil {
			t.Fatalf("unmarshal stream fixture: %v", err)
		}
		if got := codecString(s); got != "" {
			t.Errorf("codecString = %q, want \"\" (publish degrades a foreign tag, fail-open)", got)
		}
	})

	// Scenario: Matroska-sourced HEVC answers the composed sample entry.
	// The stored source facts carry the REAL prod shape — hevc, profile
	// "Main 10", level 120 as a JSON number, codec_tag_string
	// "[0][0][0][0]", two aac LC streams — and the legacy composition pins
	// hvc1.2.4.L120.B0 plus the deduped mp4a.40.2.
	t.Run("legacy_matroska_hevc_record", func(t *testing.T) {
		const doc = `{"streams":[` +
			`{"codec_type":"video","codec_name":"hevc","codec_tag_string":"[0][0][0][0]","profile":"Main 10","level":120},` +
			`{"codec_type":"audio","codec_name":"aac","profile":"LC"},` +
			`{"codec_type":"audio","codec_name":"aac","profile":"LC"}],` +
			`"format":{"format_name":"matroska"}}`
		var f map[string]any
		if err := json.Unmarshal([]byte(doc), &f); err != nil {
			t.Fatalf("unmarshal ffprobe fixture: %v", err)
		}
		got := legacyCodecs(f)
		want := []string{"hvc1.2.4.L120.B0", "mp4a.40.2"}
		if !reflect.DeepEqual(got, want) {
			t.Errorf("legacyCodecs = %v, want %v (sample entry composed, audio deduped)", got, want)
		}
	})

	t.Run("recorded_at_publish", func(t *testing.T) {
		dir := t.TempDir()
		fixture := makeH264Fixture(t, dir, 12*time.Second)
		s := newTestService(t, filepath.Join(dir, "streams"), 5*time.Second) // head 5s + tail 7s: both phases run

		build, err := s.Pack(ctx, "it_cd", fixture, map[string]any{"format": map[string]any{"duration": "12.0"}}, nil)
		if err != nil {
			t.Fatalf("Pack: %v", err)
		}
		buildDir := filepath.Join(s.Root, "it_cd", build.Nonce)
		if len(build.Codecs) != 2 {
			t.Fatalf("Build.Codecs = %v, want [avc1 entry, mp4a.40.2]", build.Codecs)
		}
		if !strings.HasPrefix(build.Codecs[0], "avc1.") {
			t.Errorf("Build.Codecs[0] = %q, want an avc1 entry first", build.Codecs[0])
		}
		if build.Codecs[1] != "mp4a.40.2" {
			t.Errorf("Build.Codecs[1] = %q, want mp4a.40.2", build.Codecs[1])
		}
		// The published init segment (rend0/, D3) carries h264 + AAC (sanity),
		// and the artifact is the oracle: the record must equal the
		// composition of the published playlist's own ffprobe facts.
		kinds := streamKinds(probeStreams(t, filepath.Join(buildDir, "rend0", "init.mp4")))
		if kinds["video"] != 1 || kinds["audio"] != 1 {
			t.Fatalf("published init streams = %v, want 1 video + 1 audio", kinds)
		}
		if want := oracleCodecs(t, filepath.Join(buildDir, "index.m3u8")); !reflect.DeepEqual(build.Codecs, want) {
			t.Errorf("Build.Codecs = %v, want the published playlist's composition %v", build.Codecs, want)
		}
	})

	t.Run("rendition_build_orders_audio_then_dedupes", func(t *testing.T) {
		dir := t.TempDir()
		fixture := makeH264Fixture(t, dir, 12*time.Second)
		dub1 := makeSidecarFixture(t, dir, "dub1.flac", 12*time.Second)
		dub2 := makeSidecarFixture(t, dir, "dub2.flac", 12*time.Second)
		s := newTestService(t, filepath.Join(dir, "streams"), 600*time.Second) // whole file is the head chunk: the head-only publish path

		build, err := s.Pack(ctx, "it_rend", fixture, map[string]any{"format": map[string]any{"duration": "12.0"}}, []string{dub1, dub2})
		if err != nil {
			t.Fatalf("Pack: %v", err)
		}
		// Pinned order: video, embedded audio, then the voiceovers; the two
		// identical flac sidecars dedupe to one entry.
		if len(build.Codecs) != 3 {
			t.Fatalf("Build.Codecs = %v, want [avc1 entry, mp4a.40.2, flac]", build.Codecs)
		}
		if !strings.HasPrefix(build.Codecs[0], "avc1.") || build.Codecs[1] != "mp4a.40.2" || build.Codecs[2] != "flac" {
			t.Errorf("Build.Codecs = %v, want avc1 first, embedded mp4a.40.2 second, sidecar flac last", build.Codecs)
		}
		// Oracle: the per-rendition playlists compose to the same record.
		buildDir := filepath.Join(s.Root, "it_rend", build.Nonce)
		var want []string
		want = append(want, oracleCodecs(t, filepath.Join(buildDir, "rend0", "index.m3u8"))...)
		want = append(want, oracleCodecs(t, filepath.Join(buildDir, "rend1", "index.m3u8"))...)
		want = append(want, oracleCodecs(t, filepath.Join(buildDir, "rend2", "index.m3u8"))...)
		deduped := want[:0]
		seen := map[string]bool{}
		for _, cs := range want {
			if !seen[cs] {
				seen[cs] = true
				deduped = append(deduped, cs)
			}
		}
		if !reflect.DeepEqual(build.Codecs, deduped) {
			t.Errorf("Build.Codecs = %v, want the inits' deduped composition %v", build.Codecs, deduped)
		}
	})

	t.Run("uncomposable_stream_degrades_absent", func(t *testing.T) {
		dir := t.TempDir()
		fixture := makeFixture(t, dir, 12*time.Second) // mpeg4 video: outside the table
		s := newTestService(t, filepath.Join(dir, "streams"), 600*time.Second)

		build, err := s.Pack(ctx, "it_dg", fixture, map[string]any{"format": map[string]any{"duration": "12.0"}}, nil)
		if err != nil {
			t.Fatalf("Pack: %v", err)
		}
		if build.Codecs != nil {
			t.Errorf("Build.Codecs = %v, want nil (fail-open degradation, pack still lands)", build.Codecs)
		}
	})
}

// makeH264Fixture generates one tiny MKV with an h264 video track and an AAC
// audio track — a fixture the composition table can fully describe (the
// makeFixture fixture's mpeg4 video is deliberately uncomposable). The video
// carries 2s keyframes (-force_key_frames) so a pack of it segments the way
// real media does — without one, libx264's default GOP puts the only keyframe
// at 0 and the whole head becomes a single segment, which ffprobe probes
// WITHOUT the aac profile fact (the composition then degrades fail-open, per
// the table's rule). Returns the absolute path. No network, in-process.
func makeH264Fixture(t *testing.T, dir string, dur time.Duration) string {
	t.Helper()
	requireFFmpeg(t)
	out := filepath.Join(dir, "h264.mkv")
	secs := strconv.FormatFloat(dur.Seconds(), 'f', 2, 64)
	args := []string{
		"-nostdin", "-y",
		"-f", "lavfi", "-i", "testsrc2=size=128x72:rate=10:duration=" + secs,
		"-f", "lavfi", "-i", "sine=frequency=440:sample_rate=44100:duration=" + secs,
		"-map", "0:v", "-map", "1:a",
		"-c:v", "libx264", "-pix_fmt", "yuv420p", "-force_key_frames", "expr:gte(t,n_forced*2)", "-c:a", "aac",
		out,
	}
	if b, err := exec.Command("ffmpeg", args...).CombinedOutput(); err != nil {
		t.Fatalf("h264 fixture generation failed: %v: %s", err, truncate(b, 400))
	}
	return out
}

// makeSidecarFixture generates one tiny audio-only FLAC voiceover sidecar (a
// native encoder, no external libs; flac is an admitted family so the sidecar
// stays composable). Returns the absolute path.
func makeSidecarFixture(t *testing.T, dir, name string, dur time.Duration) string {
	t.Helper()
	requireFFmpeg(t)
	out := filepath.Join(dir, name)
	secs := strconv.FormatFloat(dur.Seconds(), 'f', 2, 64)
	args := []string{
		"-nostdin", "-y",
		"-f", "lavfi", "-i", "sine=frequency=660:sample_rate=44100:duration=" + secs,
		"-c:a", "flac",
		out,
	}
	if b, err := exec.Command("ffmpeg", args...).CombinedOutput(); err != nil {
		t.Fatalf("sidecar fixture generation failed: %v: %s", err, truncate(b, 400))
	}
	return out
}

// oracleCodecs ffprobes path directly (a published playlist or init segment)
// and composes the expected codec record from the artifact's own facts — the
// test-side oracle the recorded Build.Codecs must equal (the artifact decides,
// not the source document).
func oracleCodecs(t *testing.T, path string) []string {
	t.Helper()
	var out []string
	for _, s := range probeStreams(t, path) {
		name, _ := s["codec_name"].(string)
		switch name {
		case "h264":
			prefixes := map[string]string{
				"Baseline": "4200", "Constrained Baseline": "4240", "Main": "4D40", "High": "6400",
			}
			profile, _ := s["profile"].(string)
			level, _ := s["level"].(float64)
			prefix, ok := prefixes[profile]
			if !ok || level < 1 {
				t.Fatalf("oracle cannot compose the artifact's h264 facts (profile %q level %v)", profile, level)
			}
			out = append(out, fmt.Sprintf("avc1.%s%02X", prefix, int(level)))
		case "aac":
			profile, _ := s["profile"].(string)
			if profile != "LC" {
				t.Fatalf("oracle found non-LC aac (profile %q) in the artifact", profile)
			}
			out = append(out, "mp4a.40.2")
		case "flac":
			out = append(out, "flac")
		default:
			t.Fatalf("oracle found an uncomposable stream (%q) in the artifact", name)
		}
	}
	return out
}
